                # check if current cell's perpendicular coord in band and inside a block
                p = cc if dr!=0 else rr
                if p in band and (rr,cc) in bat and bat[(rr,cc)] not in rec:
                    b=bat[(rr,cc)]; rec.add(b)
                    cells=bls[b]
                    band = set(c for (_,c) in cells) if dr!=0 else set(r for (r,_) in cells)
            rr+=dr; cc+=dc
